{
  "scenario_title": "Monthly farebox recovery, operating costs, and boarding efficiency across transit modes and divisions, 2021-2023",
  "data_context": "The Metropolitan Transit Authority performance analytics division compiled monthly route-level operating logs, fare collection summaries, and financial reports from January 2021 through December 2023 to evaluate cost efficiency and farebox recovery across service types.",
  "script": "dim(\"transit_mode\", [\"Local Bus\", \"BRT\", \"Light Rail\", \"Commuter Rail\"], weights=[0.45, 0.20, 0.25, 0.10], group=\"network\")\ndim(\"operating_division\", [\"Central\", \"North\", \"South\", \"East\"], parent=\"transit_mode\", weights={\"Local Bus\": [0.35, 0.25, 0.25, 0.15], \"BRT\": [0.50, 0.20, 0.20, 0.10], \"Light Rail\": [0.40, 0.30, 0.20, 0.10], \"Commuter Rail\": [0.25, 0.25, 0.25, 0.25]}, group=\"network\")\ndim(\"fare_tier\", [\"Standard Adult\", \"Discounted Youth/Senior\", \"Monthly Pass\", \"Corporate Bulk\"], weights=[0.45, 0.20, 0.25, 0.10], group=\"fare_mix\")\n\ntime(\"month\", start=\"2021-01-01\", end=\"2023-12-31\", freq=\"monthly\")\n\nmeasure(\"boardings_per_rev_hour\", \"clip(gaussian(32 + 15*[transit_mode=Light Rail] + 8*[transit_mode=BRT] - 10*[transit_mode=Commuter Rail] + 4*sin(month/60), 6), 5, 80)\", unit=\"riders/hour\", additive=False)\nmeasure(\"operating_cost_per_rev_hour\", \"clip(gaussian(145 + 90*[transit_mode=Light Rail] + 160*[transit_mode=Commuter Rail] + 15*[transit_mode=BRT] + 0.03*month, 18), 80, 500)\", unit=\"USD/hour\", additive=False)\nmeasure(\"average_fare_collected\", \"clip(gaussian(1.75 + 2.50*[transit_mode=Commuter Rail] + {\\\"Standard Adult\\\": 0.60, \\\"Discounted Youth/Senior\\\": -0.75, \\\"Monthly Pass\\\": -0.20, \\\"Corporate Bulk\\\": 0.15}[fare_tier], 0.25), 0.50, 6.00)\", unit=\"USD\", additive=False)\nmeasure(\"farebox_recovery_ratio\", \"clip((boardings_per_rev_hour * average_fare_collected) / operating_cost_per_rev_hour * 100, 5, 95)\", unit=\"%\", additive=False)\nmeasure(\"total_revenue_hours\", \"poisson(350 + 100*[transit_mode=Local Bus] + 50*[operating_division=Central])\", unit=\"hours\", additive=True)\n\nemit(1800)",
  "intents": [
    {
      "sentence": "Operating cost per revenue hour across transit modes",
      "columns": [
        "transit_mode",
        "operating_cost_per_rev_hour"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    },
    {
      "sentence": "Farebox recovery ratio trend over time by transit mode",
      "columns": [
        "month",
        "farebox_recovery_ratio"
      ],
      "aggregate": "AVG",
      "family": "trend"
    },
    {
      "sentence": "Relationship between boardings per revenue hour and farebox recovery ratio",
      "columns": [
        "boardings_per_rev_hour",
        "farebox_recovery_ratio"
      ],
      "aggregate": "NONE",
      "family": "relation"
    },
    {
      "sentence": "Total revenue hours by operating division",
      "columns": [
        "operating_division",
        "total_revenue_hours"
      ],
      "aggregate": "SUM",
      "family": "composition"
    }
  ]
}
